// 전체 부모RET와 실제 중첩 Console/버퍼를 실행한 독립 관측을 직접 비교한다.
TEST_CASE(ChatWindow_IndependentNativeCreationInputHelperAndLifetime) {
    std::ifstream input(NETSTORM_CHAT_WINDOW_FIXTURE);CHECK(input.good());std::string line;std::size_t rows{};
    while (std::getline(input,line)) { // 앞21열은 입력이며 뒤10열은 실제 PE 관측이다.
        if (line.empty() || line.starts_with("name\t")) continue;const auto row=EntrySplit(line,'\t');CHECK(row.size()==31);if (row.size()!=31) continue;const auto failures=netstorm::test::FailureCount();ChatScene scene(row);const auto& operation=row[1];std::uint32_t result{};
        if (operation=="construct") scene.chat->Construct(kChatRoot,EntrySigned(EntryNumber(row[2])),EntrySigned(EntryNumber(row[3])));else if (operation=="create") scene.chat->Create();else if (operation=="destroy") scene.chat->Destruct(kChatRoot);else if (operation=="normalize") scene.chat->NormalizePrefix(kChatRoot);
        else { const auto bytes=EntryBytes(row[7]);const auto text=std::string(bytes.begin(),bytes.end());result=scene.chat->Handle(kChatRoot,EntryNumber(row[4]),EntryNumber(row[5]),row[6]=="~" ? kChatPayload : EntryNumber(row[6]),row[6]=="~" ? std::optional<std::string_view>{text} : std::nullopt); }
        CHECK(EntryPacked(scene.RootFields())==row[21]);CHECK(EntryPacked(EntryFields(scene.node))==row[22]);CHECK(EntryPacked(std::array<std::uint32_t,4>{scene.scrolling.buffer,scene.scrolling.ownsBuffer,scene.scrolling.textFlags,scene.scrolling.callback})==row[23]);CHECK(ChatHex(scene.root.inputPrefix.data())==row[24]);CHECK(ChatHex(scene.buffer->Text())==row[25]);CHECK(scene.CompletionFields()==row[26]);CHECK((scene.trace.empty() ? "-" : scene.trace)==row[27]);CHECK(result==EntryNumber(row[28]));CHECK(EntryNumber(row[29])==(operation=="construct" ? 12U : operation=="handle" ? 16U : 4U));CHECK(EntryNumber(row[30])>0);++rows;
        if (netstorm::test::FailureCount()!=failures) { std::fprintf(stderr,"ChatWindow native 입력: %s/%s\n",row[0].c_str(),operation.c_str());if (scene.trace!=row[27]) { const auto mismatch=std::mismatch(scene.trace.begin(),scene.trace.end(),row[27].begin(),row[27].end());const auto offset=std::size_t(mismatch.first-scene.trace.begin());std::fprintf(stderr,"trace offset=%zu actual=%s expected=%s\n",offset,scene.trace.substr(offset,160).c_str(),row[27].substr(offset,160).c_str()); } } // 첫 차이부터 표시하여 원문 인자·호출순서를 추적한다.
    }
    CHECK(rows==180);
}
